import bordersData from "./borders.json";

// Server only: borders.json is 1.6 MB. Generated by scripts/generate-borders.mjs.

type Ring = [number, number][]; // [lng, lat]
type Polygon = Ring[]; // [outer, ...holes]

interface Country {
  code: string;
  polygons: Polygon[];
  bbox: { w: number; e: number; s: number; n: number };
}

const EARTH_RADIUS_M = 6_371_008.8;
const toRad = (deg: number) => (deg * Math.PI) / 180;

const COUNTRIES: Country[] = Object.entries(bordersData as unknown as Record<string, Polygon[]>).map(
  ([code, polygons]) => {
    let w = 180, e = -180, s = 90, n = -90;
    for (const polygon of polygons)
      for (const [lng, lat] of polygon[0]) {
        w = Math.min(w, lng); e = Math.max(e, lng); s = Math.min(s, lat); n = Math.max(n, lat);
      }
    return { code, polygons, bbox: { w, e, s, n } };
  }
);

function inRing(lng: number, lat: number, ring: Ring) {
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const [xi, yi] = ring[i];
    const [xj, yj] = ring[j];
    if (yi > lat !== yj > lat && lng < ((xj - xi) * (lat - yi)) / (yj - yi) + xi) inside = !inside;
  }
  return inside;
}

function inCountry(country: Country, lat: number, lng: number) {
  const { w, e, s, n } = country.bbox;
  if (lat < s || lat > n || lng < w || lng > e) return false;
  return country.polygons.some(
    (polygon) => inRing(lng, lat, polygon[0]) && !polygon.slice(1).some((hole) => inRing(lng, lat, hole))
  );
}

function haversine(lat1: number, lng1: number, lat2: number, lng2: number) {
  const dLat = toRad(lat2 - lat1);
  const dLng = toRad(lng2 - lng1);
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLng / 2) ** 2;
  return 2 * EARTH_RADIUS_M * Math.asin(Math.min(1, Math.sqrt(h)));
}

// Distance from the point to the segment a–b, in a flat projection centred
// on the point. Only used near the nearest border vertex, where that's
// accurate.
function segmentDistance(lat: number, lng: number, a: [number, number], b: [number, number]) {
  const k = Math.cos(toRad(lat));
  const project = ([pLng, pLat]: [number, number]) => {
    let dLng = pLng - lng;
    if (dLng > 180) dLng -= 360;
    if (dLng < -180) dLng += 360;
    return [toRad(dLng) * k * EARTH_RADIUS_M, toRad(pLat - lat) * EARTH_RADIUS_M];
  };
  const [ax, ay] = project(a);
  const [bx, by] = project(b);
  const dx = bx - ax;
  const dy = by - ay;
  const lengthSq = dx * dx + dy * dy;
  const t = lengthSq === 0 ? 0 : Math.max(0, Math.min(1, -(ax * dx + ay * dy) / lengthSq));
  return Math.hypot(ax + t * dx, ay + t * dy);
}

// Distance from the point to the country's border: 0 if it's inside.
// Finds the nearest border vertex by great-circle distance, then refines
// against the two border segments either side of it.
function distanceToCountry(country: Country, lat: number, lng: number) {
  if (inCountry(country, lat, lng)) return 0;
  let best = Infinity;
  let bestRing: Ring | null = null;
  let bestIndex = 0;
  for (const polygon of country.polygons) {
    const ring = polygon[0];
    for (let i = 0; i < ring.length; i++) {
      const d = haversine(lat, lng, ring[i][1], ring[i][0]);
      if (d < best) {
        best = d;
        bestRing = ring;
        bestIndex = i;
      }
    }
  }
  if (!bestRing) return best;
  const n = bestRing.length;
  const vertex = bestRing[bestIndex];
  return Math.min(
    best,
    segmentDistance(lat, lng, bestRing[(bestIndex - 1 + n) % n], vertex),
    segmentDistance(lat, lng, vertex, bestRing[(bestIndex + 1) % n])
  );
}

// Natural Earth's 1:50m outlines smooth the coastline by up to several km,
// so a click on a waterfront city can land "offshore". A click in water
// this close to a country counts as in it. (Clicks on land always belong to
// the country they're in, so this never makes a land-border guess count
// for two countries.)
export const COAST_TOLERANCE_M = 5000;

// Where a guess landed: its country (null for open water) and its distance
// (m, rounded) to every country's border, 0 for the country it's in. The
// full table goes to the database so the guess route never needs to know
// which country is the answer.
export function locateGuess(lat: number, lng: number): { country: string | null; distances: Record<string, number> } {
  const distances: Record<string, number> = {};
  for (const c of COUNTRIES) distances[c.code] = Math.round(distanceToCountry(c, lat, lng));

  let country = Object.keys(distances).find((code) => distances[code] === 0) ?? null;
  if (!country) {
    const [nearest, d] = Object.entries(distances).reduce((a, b) => (b[1] < a[1] ? b : a));
    if (d <= COAST_TOLERANCE_M) {
      country = nearest;
      distances[nearest] = 0;
    }
  }
  return { country, distances };
}
